import java.util.*;

class Solution {
  public long maximumSum(List<Integer> nums) {
    int n = nums.size();
    Map<Integer, Long> sums = new HashMap<>();
    long answer = 0;
    for (int i = 1; i <= n; i++) {
      int x = i, kernel = 1;
      for (int p = 2; p * p <= x; p++) {
        int parity = 0;
        while (x % p == 0) {
          x /= p;
          parity ^= 1;
        }
        if (parity == 1) kernel *= p;
      }
      if (x > 1) kernel *= x;
      long total = sums.getOrDefault(kernel, 0L) + nums.get(i - 1);
      sums.put(kernel, total);
      answer = Math.max(answer, total);
    }
    return answer;
  }
}
